/// Does this source hold any PROGRAM at all, or is it only comments and blank lines?
///
/// The question [`root_is_bare`] asks of a MIGRATED root, asked of any source. They are deliberately
/// two functions: `root_is_bare` also requires the generated `include!`, which is the right test for
/// "this crate is one step from the floor" and the wrong one for a crate that has never been wired —
/// the five this capability exists for have no `include!` and never had.
pub(crate) fn holds_no_code(src: &str) -> bool {
    src.lines().all(|l| {
        let t = l.trim();
        t.is_empty() || t.starts_with("//")
    })
}
